-- PAPER-LEARN-PROBATION-SETTLE-1 part 7 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 5406 to 5537 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_07 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_07 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_07 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_07)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_07 AS SELECT * FROM paper_learnings WHERE id IN (5406, 5426, 5468, 5470, 5473, 5477, 5478, 5479, 5480, 5487, 5488, 5489, 5490, 5497, 5498, 5499, 5500, 5516, 5517, 5519, 5520, 5522, 5523, 5535, 5537);

UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): requiring a breach to persist across consecutive cycles (or a hysteresis band) before a ticket is filed is the fix for the close-and-reopen churn that issue measures.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5406 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; selfchange): Amendments are stability-checked as steps of a recursive process: changes to prompts, code, config, crons and routing are versioned, backed up, deployed only through the canonical path, probed before and after, and reverted on a guard breach (DEPLOY-PROBES-1, canary_revert.py), one change per component at a time.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5426 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The scope conditions of the incompleteness theorems are a point of logic about when they may be cited; no fleet rule or loop invokes them, so a doctrine clause would govern nothing the fleet does. Re-propose with a fleet document that misused a formal limit.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5468 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; watchdog): Runtime watchdogs rather than static prediction already exist: the dispatcher reaps any run still running after two hours as orphaned (CRON-ADVANCE-FIRST-1 in fleet-exec), cron-watch reads cron faults every cycle, LOOP-WATCH-1 files loop-stale issues, and workflows carry timeout_ms.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5470 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Misapplying Goedel''s theorems to theology or law is a point about the paper''s subject; flagging it is a content review of one topic, and the pipeline reviewer already reads each paper. Re-propose with a published paper that made such a transfer.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5473 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): Sidak stacking over a max-statistic is a correction rule for that detector; the fleet''s triggers apply no multiplicity correction to double count, and the false-positive churn they cause is owned by TRIGGER-FLAP-1 (agent_issues 1000459).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5477 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): requiring a combined set of preconditions (a resolvable signal over enough observation windows) before a trigger files or a probe closes is the band and minimum-run fix that issue applies.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5478 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Fleet metrics are windowed counts and rates, not structured series scanned for oscillation, so there is no embedded baseline to subtract; no breach is shown to come from an uncorrected diurnal or deploy-driven step. Re-propose with such a breach.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5479 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Computing N_eff for a scan over many bins applies to the paper''s frequency scan; fleet triggers are one per metric and their false-positive churn is measured and owned in TRIGGER-FLAP-1 (agent_issues 1000459, 167 reopens on 44 tickets). Re-propose with the false-positive share left after that issue lands.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5480 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; merge): No unverified model output merges: a pull request passes pr-checks (versions, scans), the REVIEW-GATE-1 read by two disjoint families for risky diffs, and the stale-PR lane only merges a green, quiet pull request; deploys are probed and reverted on regression.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5487 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; invariants): Cross-checks between independently produced units run every cycle: v_issue_accounting (entered = open + closed + superseded), the fleet graph drift findings, mirror-guard and version-bump-guard on worker mirrors, and the failure-mode detectors.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5488 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; canary): Rollouts are staged and canaried: a control-plane change is merged only when its worker has a versioned /health, canaried for the new VERSION and reverted on failure (CONTROL-PLANE-SELF-MERGE-1), and DEPLOY-PROBES-1 baselines routes before the push.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5489 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; caps): Work units are sized to what one run can finish: COST-CUT-CODE-1 (#7247) adds a patch-too-large stop and dear-rung output caps to the code loop, CODE-BATCH-SAMEFILE-1 batches queued tasks on one file, and contracts carry max_items and budget_ms.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5490 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): Metrics carry their referent and their proxy status: each metric row states its formula and source_of_truth, OUTPUT-QUALITY-LEDGER-1 labels proxies in output_quality_measures, and READER-YIELD-1 records that clicks are not readers.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5497 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; control): Doctrine rules and gates are audited for the premise they rest on: DOCTRINE-1 requires control_registry (disposition, critical path, tested alternate) for every hold, filter, gate or cap, belief_registry with a belief-<key> probe for each belief acted on, and v_doctrine_scorecard_v2 grades them each tick.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5498 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; premise): The metric as the wrong instrument is handled: a remedy that did not move its metric in 7 days is replaced and a wrong target corrected with evidence (METRIC-CLOSED-LOOP-1), and blocker_redteam records false beliefs removed.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5499 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): An audit pass is not coverage evidence: the guard metrics remediation_latest_pass_pct_7d and issue_wontfix_share_7d (0.0) keep the loop honest, a fix whose latest verification row fails is not counted, and unverified_blocker_claims (36) lists claims nobody tested.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5500 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; taxonomy): A named, checkable failure taxonomy exists: failure_modes holds root cause, symptom, blast radius and an fm-<key> detector per mode (v_failure_mode_status reads 569), and the claim gate and review gate classify what they hold.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5516 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; verifylayers): Verification layers are themselves checked: the guard remediation_latest_pass_pct_7d, the probe-line-sweep task, the rule that a contract probe must fail while the defect exists (VACUOUS-PROBE handling), and DEPLOY-PROBES-1 requiring --live runs before a new probe can revert anything.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5517 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; birth): Every filed issue states in its closing probe what observation closes it, written at birth (519 open issues, 0 without a contract), and METRIC-TRIGGER tickets get their trigger''s probe from contract_probe_templates_v1.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5519 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; provenance): Provenance is disclosed: pipeline papers carry a Provenance and AI Involvement section (the triage reader strips it from claims), pull requests end with a generated-with attribution line and commits carry a Co-Authored-By trailer, and CLAIM-INTEGRITY-1 holds claims the work does not support.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5520 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; canary): Checks are anchored to live state rather than output markers: remediation probes read D1 rows, HTTP routes and code on main, deploy probes run declared routes, and the claim gate combines a deterministic scan with a two-model extraction.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5522 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Loops already bound audit cost per run (PL_TRIAGE_EXAMINE = 12 learnings a tick, contracts carry max_items and budget_ms) so sampled administration is the default; no audit stage is shown to have run unaffordably. Re-propose with an audit stage whose cost exceeded its budget.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5523 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; citewatch): Generation-specific checks exist for papers: CITE-FULLTEXT-1 grounds each citation on a full text and drops a work it cannot read, qnfo-citation-watch watches citations, and the claim gate holds overstated empirical claims.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5535 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; verifylayers): Periodic self-audit of the verification layers exists (guard metrics remediation_latest_pass_pct_7d, the probe-line-sweep task, v_doctrine_scorecard_v2 and control_registry reviews of every gate).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 5537 AND fleet_status = 'probation';
